// MT2009_PLUS_DROP_WIKI_V2 (chests): every chest of special_item_group.txt - a group whose number is an
// item, opened as GiveItemFromSpecialItemGroup opens it - with what one opening gives: one entry by
// weight, or each entry at its own percent (type pct); a group inside a group by its share. The bonus
// groups (type special) are no chests. For the drop wiki's item pages (cmd_general.cpp).
static void DropWikiAddChestGroup(std::vector<TDropWikiRow>& rows, const CSpecialItemGroup* group, double chance, int depth)
{
	if (!group || group->IsEmpty() || depth > PLAYERBOT_MOB_PREVIEW_MAX_DEPTH || chance <= 0.0)
		return;
	const std::vector<CSpecialItemGroup::CSpecialItemInfo> items = group->GetItems();
	const std::vector<int> probs = group->GetProbs();
	const bool pct = group->GetGroupType() == CSpecialItemGroup::PCT;
	const double total = (double) probs.back();
	if (!pct && total <= 0.0)
		return;
	for (size_t i = 0; i < items.size() && i < probs.size(); ++i)
	{
		const double weight = (double) (probs[i] - (i ? probs[i - 1] : 0));
		const double share = pct ? weight / 100.0 : weight / total;
		if (items[i].isSpecial)
			DropWikiAddChestGroup(rows, ITEM_MANAGER::instance().GetSpecialItemGroup(items[i].vnum), chance * share, depth + 1);
		else
			DropWikiAdd(rows, items[i].vnum, items[i].count, chance * share);
	}
}

void ITEM_MANAGER::GetDropWikiChests(std::vector<std::pair<DWORD, std::vector<TDropWikiRow> > >& chests)
{
	chests.clear();
	for (const auto& entry : m_map_pkSpecialItemGroup)
	{
		const CSpecialItemGroup* group = entry.second;
		if (!group || group->IsEmpty() || group->GetGroupType() == CSpecialItemGroup::SPECIAL || !GetTable(entry.first))
			continue;
		std::vector<TDropWikiRow> rows;
		DropWikiAddChestGroup(rows, group, 1.0, 0);
		if (rows.empty())
			continue;
		std::sort(rows.begin(), rows.end(), [](const TDropWikiRow& a, const TDropWikiRow& b)
		{
			if (a.dChance != b.dChance)
				return a.dChance > b.dChance;
			return a.dwVnum < b.dwVnum;
		});
		chests.emplace_back(entry.first, rows);
	}
}

